/* Wiemer reveals, all CSS. Each one is tied to an element's trip into the window (a view
   timeline) and ends over a fixed scroll distance after the element's top edge enters, so
   tall headings finish as quickly as short ones. Without scroll-driven animations, or with
   reduced motion, nothing moves and everything is in place. */

@supports (animation-timeline: view()) {
  @media (prefers-reduced-motion: no-preference) {
    /* Split text: the heading carries one named timeline; every letter reads it with its
       own start, --i letters later. The word around each letter clips it, so letters
       rise out of their line like type set from below. */
    .wiemer-split {
      view-timeline-name: --wiemer-split;
    }
    .wiemer-split-char {
      animation: wiemer-reveal-letter both cubic-bezier(0.22, 1, 0.36, 1);
      animation-timeline: --wiemer-split;
      animation-range: entry calc(var(--i, 0) * var(--wiemer-step, 9px)) entry calc(var(--wiemer-run, 260px) + var(--i, 0) * var(--wiemer-step, 9px));
    }

    .wiemer-reveal-fade,
    .wiemer-reveal-rise {
      animation-timing-function: cubic-bezier(0.22, 1, 0.36, 1);
      animation-fill-mode: both;
      animation-timeline: view();
      animation-range: entry calc(var(--wiemer-delay, 0px)) entry calc(240px + var(--wiemer-delay, 0px));
    }
    .wiemer-reveal-fade { animation-name: wiemer-reveal-fade; }
    .wiemer-reveal-rise { animation-name: wiemer-reveal-rise; }

    /* fade-out: scrubbed as the block leaves through the top of the window */
    .wiemer-reveal-fadeout {
      animation: wiemer-reveal-fadeout linear both;
      animation-timeline: view();
      animation-range: exit 0% exit 70%;
    }

    /* drift: the frame names the timeline; the picture inside slides against it */
    .wiemer-drift-frame {
      view-timeline-name: --wiemer-drift;
    }
    .wiemer-reveal-drift {
      animation: wiemer-reveal-drift linear both;
      animation-timeline: --wiemer-drift;
      animation-range: cover 0% cover 100%;
    }
  }
}

@keyframes wiemer-reveal-letter {
  from { opacity: 0; transform: translateY(var(--wiemer-rise, 105%)); }
}
@keyframes wiemer-reveal-fade {
  from { opacity: 0; }
}
@keyframes wiemer-reveal-rise {
  from { opacity: 0; transform: translateY(24px); }
}
@keyframes wiemer-reveal-fadeout {
  to { opacity: 0; }
}
@keyframes wiemer-reveal-drift {
  from { transform: translateY(calc(-1 * var(--wiemer-drift, 46px))); }
  to { transform: translateY(var(--wiemer-drift, 46px)); }
}

import { Fragment, type CSSProperties, type ElementType } from "react";
import { cn } from "@foundry/foundry-utils";
import "./wiemer-reveal.css";

/**
 * fade: opacity 0→1 · rise: fade + a 24px lift (paragraphs) · fadeout: opacity 1→0 while
 * leaving through the top · drift: a parallax slide inside a frame named by wiemerDriftFrame
 */
export type WiemerRevealEffect = "fade" | "rise" | "fadeout" | "drift";

/** The class for an effect, to put straight on an element. */
export function wiemerReveal(effect: WiemerRevealEffect) {
  return `wiemer-reveal-${effect}`;
}

/** Class for the overflow-clip frame a drifting picture moves inside. */
export const wiemerDriftFrame = "wiemer-drift-frame";

/** Inline style: start a reveal `delay` px of scrolling later, and/or set a drift distance. */
export function wiemerRevealStyle(delay = 0, drift?: number): CSSProperties {
  return { "--wiemer-delay": `${delay}px`, ...(drift !== undefined && { "--wiemer-drift": `${drift}px` }) } as CSSProperties;
}

export interface WiemerSplitTextProps {
  /** the text; a line break ("\n") forces a new line */
  text: string;
  /** the element to render, e.g. "h1", "h2", "p" */
  as?: ElementType;
  /** lg: letters rise a full line out of a mask (display headings) · sm: letters rise 30px, quicker stagger (sublines) */
  size?: "lg" | "sm";
  className?: string;
}

/**
 * Text whose letters rise into place one after another as it scrolls into view. Static
 * HTML shows the text normally; screen readers get the plain text.
 */
export function WiemerSplitText({ text, as: Tag = "h2", size = "lg", className }: WiemerSplitTextProps) {
  let i = 0;
  const vars = (size === "lg" ? {} : { "--wiemer-rise": "30px", "--wiemer-step": "3px", "--wiemer-run": "200px" }) as CSSProperties;
  return (
    <Tag className={cn("wiemer-split", className)} style={vars}>
      <span className="sr-only">{text}</span>
      <span aria-hidden="true">
        {text.split("\n").map((line, l) => (
          <Fragment key={l}>
            {l > 0 && <br />}
            {line.split(" ").map((word, w) => (
              <Fragment key={w}>
                {w > 0 && " "}
                <span className="-mb-[0.14em] inline-block overflow-clip pb-[0.14em] align-top">
                  {Array.from(word).map((char, c) => (
                    <span key={c} className="wiemer-split-char inline-block" style={{ "--i": i++ } as CSSProperties}>
                      {char}
                    </span>
                  ))}
                </span>
              </Fragment>
            ))}
          </Fragment>
        ))}
      </span>
    </Tag>
  );
}
